   5: pub fn password_reader_count(file_path: PathBuf) -> Result<usize, std::io::Error> {
   6:     // compute the number of lines in the file
   7:     let file = File::open(file_path)?;
   8:     let mut reader = BufReader::new(file);
   9:     let mut total_password_count = 0;
  10:     let mut line_buffer = Vec::new();
  11:     loop {
  12:         // count line number without reallocating each line
  13:         // read_until to avoid UTF-8 validation (unlike read_line which produce a String)
  14:         let res = reader.read_until(b'\n', &mut line_buffer)?;
  15:         if res == 0 {
  16:             // end of file
  17:             break;
  18:         }
  19:         line_buffer.clear();
  20:         total_password_count += 1;
  21:     }
  22:     Ok(total_password_count)
  23: }
