/// Resolve a built-in charset token character to its charset.
fn resolve_builtin_token(token: char) -> Option<Vec<char>> {
    match token {
        'l' => Some(charset_lowercase_letters()),
        'u' => Some(charset_uppercase_letters()),
        'd' => Some(charset_digits()),
