}

impl AesInfo {
    pub const fn new(aes_key_length: usize, verification_value: [u8; 2], salt: Vec<u8>) -> Self {
        // derive a key from the password and salt
        // the length depends on the aes key length
        let derived_key_length = 2 * aes_key_length + 2;
        Self {
